module lms_filter (
    input clk,
    input reset,
    input signed [15:0] x, // input signal
    input signed [15:0] d, // desired signal
    output signed [15:0] y  // output signal
);
    parameter N = 5; // Number of taps
    parameter STEP_SIZE = 16'h0001; // Step size (0.01 in fixed point)

    reg signed [15:0] w [0:N-1]; // weights
    reg signed [15:0] x_buf [0:N-1]; // input buffer
    reg signed [15:0] y_reg; // output register
    integer i;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Reset weights and buffers
            for (i = 0; i < N; i = i + 1) begin
                w[i] <= 16'h0000;
                x_buf[i] <= 16'h0000;
            end
            y_reg <= 16'h0000;
        end else begin
            // Shift input buffer
            for (i = N-1; i > 0; i = i - 1) begin
                x_buf[i] <= x_buf[i-1];
            end
            x_buf[0] <= x;

            // Compute output
            y_reg <= 0;
            for (i = 0; i < N; i = i + 1) begin
                y_reg <= y_reg + w[i] * x_buf[i];
            end

            // Update weights
            for (i = 0; i < N; i = i + 1) begin
                w[i] <= w[i] + (STEP_SIZE * (d - y_reg) * x_buf[i]);
            end
        end
    end

    assign y = y_reg;
endmodule

