module spi_master (
    input clk,
    input rst_n,
    input start,
    input [7:0] data_in,
    output reg mosi,
    output reg cs,
    input miso,
    output reg done
);
    reg [2:0] state;
    reg [2:0] bit_cnt;
    reg [7:0] shift_reg;

    localparam IDLE = 3'b000,
               SEND = 3'b001,
               WAIT = 3'b010,
               DONE = 3'b011;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            cs <= 1;
            mosi <= 0;
            done <= 0;
            bit_cnt <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    cs <= 1;
                    if (start) begin
                        shift_reg <= data_in;
                        state <= SEND;
                        cs <= 0;
                        bit_cnt <= 0;
                    end
                end

                SEND: begin
                    if (bit_cnt < 8) begin
                        mosi <= shift_reg[7];  // Send MSB first
                        shift_reg <= {shift_reg[6:0], 1'b0}; // Shift left
                        bit_cnt <= bit_cnt + 1;
                    end else begin
                        state <= WAIT;
                    end
                end

                WAIT: begin
                    // Wait for one more clock cycle to complete
                    state <= DONE;
                end

                DONE: begin
                    cs <= 1;
                    done <= 1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end
endmodule

