module mpc_controller(
    input wire clk,
    input wire reset,
    input wire [7:0] ref_signal,
    output reg [7:0] control_signal
);
    parameter MAX_OUTPUT = 8'hFF;
    reg [7:0] prev_output;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            control_signal <= 8'b0;
            prev_output <= 8'b0;
        end else begin
            // Update control signal based on reference signal
            if (ref_signal > prev_output) begin
                control_signal <= prev_output + 1;
            end else if (ref_signal < prev_output) begin
                control_signal <= prev_output - 1;
            end else begin
                control_signal <= prev_output;
            end

            // Limit the control signal
            if (control_signal > MAX_OUTPUT) begin
                control_signal <= MAX_OUTPUT;
            end

            prev_output <= control_signal;
        end
    end
endmodule

