module RSA_Encryption (
    input [7:0] plaintext,
    input [7:0] exponent,
    output reg [15:0] ciphertext,
    input clk,
    input reset
);
    parameter [15:0] n = 16'hA5A5; // Example modulus
    reg [15:0] result;
    reg [7:0] base;
    reg [7:0] exp;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            ciphertext <= 16'b0;
            result <= 16'b1;
            base <= plaintext;
            exp <= exponent;
        end else begin
            if (exp == 8'b0) begin
                ciphertext <= result % n; // Final result
            end else begin
                if (exp[0] == 1'b1) begin
                    result <= (result * base) % n;
                end
                base <= (base * base) % n; // Square the base
                exp <= exp >> 1; // Divide exponent by 2
            end
        end
    end
endmodule

