module serializer(
    input clk,
    input reset,
    input [7:0] data_in,
    output reg serial_out,
    output reg done
);
    reg [2:0] bit_index; // 3 bits to count 0-7
    reg [7:0] data_reg;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            bit_index <= 3'b000;
            serial_out <= 1'b0;
            done <= 1'b0;
        end else if (bit_index < 3'b1000) begin
            serial_out <= data_reg[7 - bit_index];
            bit_index <= bit_index + 1;
            done <= (bit_index == 3'b0111); // done after the last bit is sent
        end else begin
            done <= 1'b1; // stays done after completing the transfer
        end
    end

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            data_reg <= 8'b0;
        end else begin
            data_reg <= data_in; // Load data on reset or when starting serialization
        end
    end
endmodule

