module temp_shutdown(
    input clk,
    input reset,
    input [7:0] temp,
    input [3:0] delay_time,
    output reg shutdown
);
    reg [3:0] counter;
    reg active;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            shutdown <= 0;
            counter <= 0;
            active <= 0;
        end else begin
            if (temp > 8'd75) begin // Threshold temperature
                active <= 1;
                counter <= 0;
            end else if (active) begin
                if (counter < delay_time) begin
                    counter <= counter + 1;
                end else begin
                    shutdown <= 1;
                end
            end
        end
    end
endmodule

