module uart_tx (
    input wire clk,
    input wire reset,
    input wire start,
    input wire [7:0] data_in,
    output reg tx,
    output reg busy
);
    parameter BAUD_RATE_DIV = 104; // Example for 9600 baud rate with 10MHz clock
    reg [3:0] state;
    reg [9:0] shift_reg;
    reg [6:0] bit_count;
    reg [6:0] baud_count;

    localparam IDLE = 4'b0000,
               START_BIT = 4'b0001,
               DATA_BITS = 4'b0010,
               STOP_BIT = 4'b0011;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            tx <= 1; // Idle state is high
            busy <= 0;
            baud_count <= 0;
            bit_count <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        shift_reg <= {1'b1, data_in, 1'b0}; // Stop bit + data + start bit
                        state <= START_BIT;
                        busy <= 1;
                        bit_count <= 0;
                        baud_count <= 0;
                    end
                end

                START_BIT: begin
                    if (baud_count == BAUD_RATE_DIV) begin
                        tx <= 0; // Start bit
                        state <= DATA_BITS;
                        baud_count <= 0;
                    end else begin
                        baud_count <= baud_count + 1;
                    end
                end

                DATA_BITS: begin
                    if (baud_count == BAUD_RATE_DIV) begin
                        tx <= shift_reg[bit_count]; // Send each bit
                        bit_count <= bit_count + 1;
                        baud_count <= 0;
                        if (bit_count == 8) begin
                            state <= STOP_BIT;
                        end
                    end else begin
                        baud_count <= baud_count + 1;
                    end
                end

                STOP_BIT: begin
                    if (baud_count == BAUD_RATE_DIV) begin
                        tx <= 1; // Stop bit
                        busy <= 0;
                        state <= IDLE;
                    end else begin
                        baud_count <= baud_count + 1;
                    end
                end
            endcase
        end
    end
endmodule

