module audio_compressor (  
    input clk,  
    input reset,  
    input [15:0] audio_in,  
    input [15:0] threshold,  
    output reg [15:0] audio_out  
);  
    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            audio_out <= 16'b0;  
        end else begin  
            if (audio_in > threshold)  
                audio_out <= threshold;  
            else  
                audio_out <= audio_in;  
        end  
    end  
endmodule

module echo_cancellation (
    input wire clk,
    input wire rst,
    input wire [15:0] input_signal,
    input wire [15:0] reference_signal,
    output reg [15:0] output_signal
);
    reg [15:0] prev_input;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            prev_input <= 16'b0;
            output_signal <= 16'b0;
        end else begin
            output_signal <= input_signal - reference_signal;
            prev_input <= input_signal;
        end
    end
endmodule

