module sram_cell (
    input wire [3:0] data_in,
    input wire rw, // rw = 1 for read, 0 for write
    output reg [3:0] data_out
);
    reg [3:0] memory;

    always @(posedge rw) begin
        if (rw == 0) begin
            // Write mode
            memory <= data_in;
        end else begin
            // Read mode
            data_out <= memory;
        end
    end
endmodule

