module ofdm_modulator (
    input clk,
    input rst,
    input [7:0] data_in, // 8-bit input data
    input valid_in,
    output reg [3:0] symbol_out, // 4-bit symbol output
    output reg valid_out // Indicates valid output
);
    reg [2:0] state; // State for FSM
    reg [7:0] buffer; // Buffer for input data
    reg [1:0] count; // Count of symbols to output

    // State encoding
    localparam IDLE = 3'b000,
               LOAD = 3'b001,
               OUTPUT = 3'b010,
               DONE = 3'b011;

    // Simple mapping: each 8-bit input maps to 4 symbols
    function [3:0] map_to_symbol;
        input [7:0] data;
        begin
            // Example mapping function
            case (data)
                8'b00000000: map_to_symbol = 4'b0001;
                8'b00000001: map_to_symbol = 4'b0010;
                8'b00000010: map_to_symbol = 4'b0011;
                8'b00000011: map_to_symbol = 4'b0100;
                // Add more mappings as necessary
                default: map_to_symbol = 4'b0000; // Default case
            endcase
        end
    endfunction

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            valid_out <= 0;
            count <= 0;
            symbol_out <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (valid_in) begin
                        buffer <= data_in;
                        state <= LOAD;
                    end
                end
                LOAD: begin
                    symbol_out <= map_to_symbol(buffer);
                    valid_out <= 1;
                    count <= count + 1;
                    state <= OUTPUT;
                end
                OUTPUT: begin
                    if (count < 4) begin
                        symbol_out <= map_to_symbol(buffer); // Output next symbol
                        count <= count + 1;
                    end else begin
                        valid_out <= 0; // No more output
                        state <= DONE;
                    end
                end
                DONE: begin
                    state <= IDLE; // Go back to idle after processing
                end
            endcase
        end
    end
endmodule

