module convolutional_encoder (
    input wire clk,
    input wire rst,
    input wire [1:0] data_in,
    output reg [3:0] data_out
);
    reg [2:0] shift_reg;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            shift_reg <= 3'b000;
            data_out <= 4'b0000;
        end else begin
            shift_reg <= {data_in, shift_reg[2:1]};
            data_out <= {
                shift_reg[2] ^ shift_reg[1] ^ shift_reg[0], // g1
                shift_reg[0] ^ shift_reg[2]                // g2
            };
        end
    end
endmodule

