module monte_carlo_lfsr (
    input wire clk,
    input wire rst,
    input wire [4:0] seed,
    output reg [4:0] random_number
);

    initial begin
        random_number = seed;
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            random_number <= seed;
        end else begin
            // Simple LFSR feedback polynomial: x^5 + x^2 + 1
            random_number <= {random_number[3:0], random_number[4] ^ random_number[1]};
        end
    end
endmodule

module comparator_64bit(
    input [63:0] a,
    input [63:0] b,
    output reg [1:0] result // 2'b00 for equal, 2'b01 for a > b, 2'b10 for a < b
);  
always @(*) begin  
    if (a > b)  
        result = 2'b01;  
    else if (a < b)  
        result = 2'b10;  
    else  
        result = 2'b00;  
end  
endmodule

