module switching_regulator (
    input wire clk,
    input wire reset,
    input wire [7:0] error_voltage,
    input wire [7:0] voltage_ref,
    output reg pwm_signal
);
    reg [7:0] duty_cycle;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            pwm_signal <= 0;
            duty_cycle <= 0;
        end else begin
            duty_cycle <= (error_voltage > voltage_ref) ? (255 - error_voltage) : error_voltage;
            pwm_signal <= (duty_cycle > 128) ? 1'b1 : 1'b0; // Simple threshold for PWM signal
        end
    end
endmodule

