module pwm_generator (  
    input clk,  
    input [3:0] duty_cycle,  
    output reg pwm_out  
);  
    reg [3:0] count;  
    always @(posedge clk) begin  
        if (count < 16)  
            count <= count + 1;  
        else  
            count <= 0;  
    end  

    always @(posedge clk) begin  
        if (count < duty_cycle)  
            pwm_out <= 1;  
        else  
            pwm_out <= 0;  
    end  
endmodule

