module simple_neuron(
    input [7:0] x1,
    input [7:0] x2,
    input clk,
    input reset,
    input [7:0] target,
    output reg y_out
);
    reg [7:0] weight1;
    reg [7:0] weight2;
    reg [7:0] bias;
    reg [7:0] output_neuron;
    reg [7:0] error;

    initial begin
        weight1 = 8'h01; // initial weights
        weight2 = 8'h01;
        bias = 8'h00; // initial bias
    end

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            weight1 <= 8'h01;
            weight2 <= 8'h01;
            bias <= 8'h00;
            y_out <= 1'b0;
        end else begin
            // Forward pass
            output_neuron <= (x1 * weight1 + x2 * weight2 + bias) >> 8; // simple scaling

            // Activation function (step function)
            y_out <= (output_neuron > 8'h7F) ? 1'b1 : 1'b0; // thresholding at 127

            // Calculate error
            error <= target - output_neuron;

            // Backward pass (weight update)
            weight1 <= weight1 + (error * x1) >> 8; // simplistic weight update
            weight2 <= weight2 + (error * x2) >> 8;
            bias <= bias + (error >> 1); // update bias
        end
    end
endmodule

module crc4_generator (  
    input wire clk,  
    input wire rst,  
    input wire [3:0] data_in,  
    output reg [3:0] crc_out  
);  
    reg [3:0] crc;  
    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            crc <= 4'b0000;  
        end else begin  
            crc[3] <= data_in[3] ^ crc[0];  
            crc[2] <= data_in[2] ^ crc[3];  
            crc[1] <= data_in[1] ^ crc[2];  
            crc[0] <= data_in[0] ^ crc[1];  
        end  
    end  
    always @(posedge clk) begin  
        crc_out <= crc;  
    end  
endmodule

module temperature_sensor_comparator (
    input [3:0] temperature,
    output reg alert
);

always @(*) begin
    if (temperature > 4'b1111) // 15 in binary
        alert = 1'b1;
    else
        alert = 1'b0;
end

endmodule
